INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000451', 'folds', 'Engineering & Technology', 'Engineering Geology', 'Technical Concept', 'Bends or curved structures formed when rock layers are deformed.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of folds within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'Core considerations include the defining characteristics of folds, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Bends or curved structures formed when rock layers are deformed. Within Geological Structures and Discontinuities, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of folds within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of folds, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'folds; Core considerations include the defining characteristics of folds, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Engineering Geology', 'Active'), ('KCR_000452', 'faults', 'Engineering & Technology', 'Engineering Geology', 'Technical Concept', 'Fractures or zones of displacement in rock along which relative movement has occurred.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of faults within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'Core considerations include the defining characteristics of faults, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Fractures or zones of displacement in rock along which relative movement has occurred. Within Geological Structures and Discontinuities, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of faults within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of faults, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'faults; Core considerations include the defining characteristics of faults, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Engineering Geology', 'Active'), ('KCR_000453', 'joints', 'Engineering & Technology', 'Engineering Geology', 'Technical Concept', 'Planar fractures in rock along which little or no displacement has occurred.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of joints within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'Core considerations include the defining characteristics of joints, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Planar fractures in rock along which little or no displacement has occurred. Within Geological Structures and Discontinuities, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of joints within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of joints, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'joints; Core considerations include the defining characteristics of joints, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Engineering Geology', 'Active'), ('KCR_000454', 'shear zones', 'Engineering & Technology', 'Engineering Geology', 'Technical Concept', 'Zones of concentrated rock deformation characterised by significant shear displacement or strain.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of shear zones within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context.', 'Core considerations include the defining characteristics of shear zones, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Zones of concentrated rock deformation characterised by significant shear displacement or strain. Within Geological Structures and Discontinuities, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of shear zones within Engineering Geology, particularly where the Geological Structures and Discontinuities module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of shear zones, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'shear zones; Core considerations include the defining characteristics of shear zones, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Engineering Geology', 'Act